"""t4 · Cobro completo (pago dividido, importe recibido, vuelto, comprobantes), operaciones de la caja y expediente,
monedero, niveles, tarjeta del Club en el celular (código que rota), avisos y baja de socios. Modo local."""
from h2 import *
t=T('t4 cobro completo, caja, monedero, niveles, tarjeta del celular')
def cob(pg,pid='p_cream',don=None,rec=None):
    go(pg,'#/panel/vender');pg.wait_for_selector(f'[data-a=posAdd][data-id={pid}]',timeout=5000)
    if rec:pick_rec(pg,rec)
    pg.click(f'[data-a=posAdd][data-id={pid}]');pg.wait_for_timeout(120)
    pg.click('[data-a=posCobrar]');pg.wait_for_selector('[data-a=cobOk]',timeout=4000)
    if don is not None:pg.fill('#donv',str(don));pg.dispatch_event('#donv','change');pg.wait_for_timeout(200)
    if pg.query_selector('#rubsel'):pg.select_option('#rubsel','r_don')
def last(pg):return st(pg,"S.sales[S.sales.length-1]")
with sync_playwright() as p:
    b,c,pg=launch(p)
    pg.goto(HTML);pg.wait_for_timeout(500);boot_admin(pg)
    open_caja(pg,1000)
    # ---------- efectivo: importe recibido obligatorio, Justo, vuelto
    cob(pg,don=18500)
    t.chk(pg.query_selector('#modal [data-a=rcvJusto]') is not None,'efectivo: aparece el importe recibido con «Justo»')
    n0=st(pg,"S.sales.length");pg.click('[data-a=cobOk]');pg.wait_for_timeout(250)
    t.chk(st(pg,"S.sales.length")==n0 and 'recibido' in toast(pg).lower(),'sin importe recibido no se registra')
    pg.fill('#rcv','10000');pg.dispatch_event('#rcv','input');pg.wait_for_timeout(100)
    t.chk('insuficiente' in pg.inner_text('#vto').lower(),'recibido menor: aviso de insuficiente')
    pg.fill('#rcv','20000');pg.dispatch_event('#rcv','input');pg.wait_for_timeout(100)
    t.chk('VUELTO A ENTREGAR' in pg.inner_text('#vto') and '1.500' in pg.inner_text('#vto'),'vuelto grande: $ 1.500')
    pg.click('[data-a=cobOk]');pg.wait_for_timeout(300)
    s=last(pg);t.chk(s['recv']==20000 and s['vuelto']==1500 and s['pays']==[{'m':'efectivo','a':18500}],'entrega con recibido, vuelto y medio')
    t.chk(pg.query_selector('#modal .vuelto') is not None,'el comprobante muestra el vuelto a entregar');close_modal(pg)
    cob(pg,don=18500);pg.click('[data-a=rcvJusto]');pg.wait_for_timeout(80);t.chk('justo' in pg.inner_text('#vto').lower(),'«Justo»: sin vuelto');pg.click('[data-a=cobOk]');pg.wait_for_timeout(250);close_modal(pg)
    # ---------- pago dividido con comprobante de transferencia
    cob(pg,don=60000);pg.click('[data-a=cobSplit]');pg.wait_for_timeout(150)
    t.chk(len(pg.query_selector_all('#modal .mxrow'))==2,'pago dividido: dos filas')
    pg.fill('#modal .mxrow:nth-of-type(1) input','40000') if False else None
    rows=pg.query_selector_all('#modal [data-in=mxa]');rows[0].fill('40000');rows[0].dispatch_event('input');rows[1].fill('10000');rows[1].dispatch_event('input');pg.wait_for_timeout(100)
    t.chk('Faltan' in pg.inner_text('#mxst'),'suma incompleta: «Faltan …»')
    pg.click('#modal [data-a=mxResto][data-i="1"]');pg.wait_for_timeout(150)
    t.chk('cierra' in pg.inner_text('#mxst'),'«Resto» completa la suma')
    pg.click('[data-a=cobOk]');pg.wait_for_timeout(200);t.chk('Falta' in toast(pg),'transferencia sin comprobante: no se registra')
    pg.fill('#pd_transferencia_ent','Banco Macro');pg.fill('#pd_transferencia_nro','OP-889 900 11');pg.fill('#pd_transferencia_fh',time.strftime('%Y-%m-%dT%H:%M'))
    for e in ['#pd_transferencia_ent','#pd_transferencia_nro','#pd_transferencia_fh']:pg.dispatch_event(e,'input')
    pg.click('[data-a=cobOk]');pg.wait_for_timeout(300)
    s=last(pg);t.chk(s['pay']=='mixto' and [x['m'] for x in s['pays']]==['efectivo','transferencia'] and s['pays'][1]['det']['nro']=='OP88990011','pago mixto con comprobante normalizado: '+str(s.get('pays')))
    close_modal(pg)
    # mismo comprobante otra vez → rechazado
    cob(pg,don=18500);pg.click('[data-a=cobPay][data-id=transferencia]');pg.wait_for_timeout(150)
    pg.fill('#pd_transferencia_ent','Otro');pg.fill('#pd_transferencia_nro','OP88990011');pg.fill('#pd_transferencia_fh',time.strftime('%Y-%m-%dT%H:%M'))
    for e in ['#pd_transferencia_ent','#pd_transferencia_nro','#pd_transferencia_fh']:pg.dispatch_event(e,'input')
    n0=st(pg,"S.sales.length");pg.click('[data-a=cobOk]');pg.wait_for_timeout(250)
    t.chk(st(pg,"S.sales.length")==n0 and 'ya se usó' in toast(pg),'el mismo N.º de operación no se usa dos veces')
    # tarjeta: número completo rechazado, no se guarda
    pg.click('[data-a=cobPay][data-id=debito]');pg.wait_for_timeout(150)
    pg.select_option('#pd_debito_brand','Visa');pg.fill('#pd_debito_last4','4242');pg.fill('#pd_debito_auth','4111111111111111');pg.fill('#pd_debito_cupon','12')
    for e in ['#pd_debito_brand','#pd_debito_last4','#pd_debito_auth','#pd_debito_cupon']:pg.dispatch_event(e,'input')
    pg.click('[data-a=cobOk]');pg.wait_for_timeout(250)
    t.chk(st(pg,"S.sales.length")==n0 and 'tarjeta completo' in toast(pg),'número de tarjeta completo: rechazado')
    t.chk(not st(pg,"JSON.stringify(S).includes('4111111111111111')"),'el número de tarjeta no quedó guardado en ningún lado')
    # sin comprobante autorizado por el administrador → a conciliar → completar
    pg.click('[data-a=cobPay][data-id=qr]');pg.wait_for_timeout(150)
    pg.click('#modal [data-a=pdSc]');pg.wait_for_selector('#askv');pg.fill('#askv','se cayó la app del banco');pg.click('[data-a=askOk]');pg.wait_for_timeout(300)
    pg.wait_for_selector('[data-a=cobOk]');pg.click('[data-a=cobOk]');pg.wait_for_timeout(300)
    s=last(pg);t.chk(s['pays'][0]['m']=='qr' and s['pays'][0].get('sc')=='se cayó la app del banco','cobro QR sin comprobante autorizado');close_modal(pg)
    go(pg,'#/panel/caja');pg.wait_for_timeout(200)
    t.chk('Pagos a conciliar' in pg.inner_text('#view'),'caja: «Pagos a conciliar»')
    pg.click('#view [data-a=expOpen][data-id="%s"]'%s['id']);pg.wait_for_selector('#modal [data-a=cdCompletar]')
    pg.click('#modal [data-a=cdCompletar]');pg.wait_for_selector('#cd_prov');pg.select_option('#cd_prov','Mercado Pago');pg.fill('#cd_txid','MP12345678');pg.click('[data-a=cdOk]');pg.wait_for_timeout(300)
