    close_modal(pg);go(pg,'#/panel/vender');go(pg,'#/panel/caja');pg.wait_for_timeout(200)
    t.chk('Pagos a conciliar' not in pg.inner_text('#view'),'ya no queda nada a conciliar')
    # ---------- arqueo: el dinero por medio cierra
