    t.chk(stt['byPay']['efectivo']==18500+18500+40000 and stt['byPay']['transferencia']==20000 and stt['byPay']['qr']==18500,'dinero por medio: '+str(stt['byPay']))
    t.chk(stt['esperado']==1000+77000,'efectivo esperado = fondo + efectivo (sin vuelto): '+str(stt['esperado']))
    # operaciones de la caja
    v=pg.inner_text('#view');t.chk('Operaciones de esta caja' in v and 'Ver detalle' in v,'operaciones de esta caja con detalle')
    pg.select_option('[data-ch=opfm]','transferencia');pg.wait_for_timeout(200)
    t.chk(len(pg.query_selector_all('#view tbody tr [data-a=expOpen]'))==1,'filtro por medio: una operación con transferencia')
    pg.select_option('[data-ch=opfm]','');pg.wait_for_timeout(150)
    sid=st(pg,"S.sales.find(x=>x.pay==='mixto').id")
    pg.click('#view [data-a=expOpen][data-id="%s"]'%sid);pg.wait_for_timeout(250);ex=pg.inner_text('#modal')
    t.chk('Expediente' in ex and 'Movimientos que generó' in ex and 'Banco Macro' in ex and 'Existencias' in ex and 'Auditoría' in ex,'expediente: encabezado, pagos, movimientos, auditoría')
    t.chk(st(pg,"S.audit.some(a=>a.a==='expediente_visto')"),'abrir el expediente queda en auditoría');close_modal(pg)
    # ---------- monedero y niveles
    add_socio(pg,'Mona','Dero',doc='30555666',wa='5493875001234',k=True,bday=time.strftime('1990-%m-%d'))
    so=st(pg,"S.socios.find(x=>x.name==='Mona Dero')")
    go(pg,'#/panel/socios');pg.wait_for_selector(f'[data-a=legajo][data-id="{so["id"]}"]');pg.click(f'[data-a=legajo][data-id="{so["id"]}"]');pg.wait_for_selector('#modal [data-a=monCargar]')
    pg.click('#modal [data-a=monCargar]');pg.wait_for_selector('#mo_m');pg.fill('#mo_m','30000');pg.select_option('#mo_med','transferencia');pg.click('[data-a=monCargarOk]');pg.wait_for_timeout(300)
    t.chk(st(pg,"__vb().monSaldo('%s')"%so['id'])==30000,'carga de monedero: saldo 30.000')
