    pg.click('[data-a=cobPay][data-id=mon]');pg.wait_for_timeout(150);pg.select_option('#rubsel','r_don');pg.click('[data-a=cobOk]');pg.wait_for_timeout(300)
    s=last(pg);t.chk(s['pays']==[{'m':'mon','a':14000}] and s['mon']==14000,'entrega pagada con monedero')
    t.chk(st(pg,"__vb().monSaldo('%s')"%so['id'])==16000,'saldo restante 16.000');close_modal(pg)
    cob(pg,pid='p_balm',don=20000,rec='Mona');pg.click('[data-a=cobPay][data-id=mon]');pg.wait_for_timeout(150);pg.select_option('#rubsel','r_don');n0=st(pg,"S.sales.length");pg.click('[data-a=cobOk]');pg.wait_for_timeout(250)
    t.chk(st(pg,"S.sales.length")==n0 and 'no alcanza' in toast(pg),'monedero sin saldo suficiente: no se registra');close_modal(pg)
    stt=st(pg,"__vb().cajaStats()");t.chk(stt['mon']==14000 and stt['esperado']==78000,'el pago con monedero no suma dinero a la caja')
    # anular devuelve el saldo
    pg.evaluate("location.hash='#/panel/vender'");pg.wait_for_timeout(200);pg.click('[data-a=posNC]') if pg.query_selector('[data-a=posNC]') else pg.evaluate("__vb();document.querySelector('[data-a=posNC]')")
    pg.wait_for_selector('#modal [data-a=ncPick]');pg.click('#modal [data-a=ncPick][data-id="%s"]'%s['id']);pg.fill('#askv','prueba');pg.click('[data-a=askOk]');pg.wait_for_timeout(300)
    t.chk(st(pg,"__vb().monSaldo('%s')"%so['id'])==30000,'anular la entrega devuelve el saldo del monedero')
    # niveles
    go(pg,'#/panel/sellos');pg.click('[data-a=fidTab][data-id=config]');pg.wait_for_selector('#fc_n')
    pg.check('#fc_n');pg.fill('#fc_p','10000');pg.fill('#fc_pp','5');pg.fill('#fc_o','50000');pg.fill('#fc_op','10');pg.click('[data-a=fidCfgOk]');pg.wait_for_timeout(250)
    t.chk(st(pg,"S.org.niveles.on&&S.org.niveles.plata===10000"),'configuración de niveles guardada')
    sale_flow(pg,'p_balm',don=14000,rubro='r_don',rec='Mona');close_modal(pg)
    t.chk(st(pg,"__vb().nivelOf(S.socios.find(x=>x.name==='Mona Dero')).k")=='plata','nivel Plata por donaciones de los últimos días')
    cob(pg,pid='p_cream',rec='Mona');t.chk('Nivel' in pg.inner_text('#modal') and 'Plata' in pg.inner_text('#modal'),'el cobro ofrece el beneficio del nivel')
    pg.click('[data-a=cobNivel]');pg.wait_for_timeout(200);t.chk(pg.input_value('#donv')=='17575','aplica 5 % menos sobre la sugerida (18.500 → 17.575)')
    close_modal(pg);pg.evaluate("(()=>{const v=__vb();v.POS.lines=[];})()")
    # ---------- tarjeta del Club en el celular
    go(pg,'#/panel/socios');pg.click(f'[data-a=legajo][data-id="{so["id"]}"]');pg.wait_for_selector('#modal [data-a=socioCard]');pg.click('#modal [data-a=socioCard]');pg.wait_for_selector('#modal [data-a=cardCopy]')
    card=st(pg,"S.socios.find(x=>x.name==='Mona Dero').card")
