    t.chk(card['sec'] not in json.dumps(st(pg,"S.audit")),'la clave de la tarjeta no queda en la auditoría')
    t.chk('tarjeta%3D' in pg.inner_html('#modal') or '#tarjeta=' in pg.inner_html('#modal'),'enlace personal para enviar por WhatsApp');close_modal(pg)
    # el celular: abre el enlace, guarda la tarjeta y muestra QR + código que rota
    ph=b.new_context().new_page();ph.goto(HTML+'#tarjeta='+card['id']+'.'+card['sec']);ph.wait_for_timeout(1200)
    t.chk(ph.url.endswith('#/mitarjeta'),'el enlace se limpia de la barra de direcciones')
    code=ph.evaluate("(async()=>{const v=__vb();return await v.cardCode(%s,v.cardWin())})()"%json.dumps(card))
