    t.chk(st(pg,"S.audit.some(a=>a.a==='sello'&&a.d.includes('\"medio\":\"qr\"'))"),'el sello queda auditado con el medio')
    pg.fill('#sl_t','TERPS2|%s|%s'%(card['id'],code));pg.click('[data-a=stampTok]');pg.wait_for_timeout(300)
    t.chk('ya se usó' in toast(pg),'el mismo código no se usa dos veces')
