    go(pg,'#/panel/sellos');pg.click('[data-a=fidTab][data-id=avisos]');pg.wait_for_timeout(200)
    t.chk('Sin Permiso' not in pg.inner_text('#view'),'sin consentimiento no aparece en avisos')
