    go(pg,'#/panel/socios');pg.click(f'[data-a=legajo][data-id="{so["id"]}"]');pg.wait_for_selector('#modal [data-a=socioBaja]');pg.click('#modal [data-a=socioBaja]');pg.wait_for_timeout(200)
    t.chk('monedero' in toast(pg),'baja bloqueada mientras tenga saldo a favor');close_modal(pg)
    go(pg,'#/panel/socios');pg.click(f'[data-a=legajo][data-id="{sp}"]');pg.wait_for_selector('#modal [data-a=socioBaja]');pg.click('#modal [data-a=socioBaja]');pg.wait_for_selector('#sb_m')
    leg=st(pg,"S.socios.find(x=>x.name==='Sin Permiso').legajo");pg.fill('#sb_m','pedido del titular');pg.fill('#sb_c','otro');pg.click('[data-a=socioBajaOk]');pg.wait_for_timeout(200)
